static const int NPARTS = 5;
static float partsMul(const Car &c, int what) {          // 0 - разгон, 1 - скорость, 2 - торможение
  float m = 1.0f;
  for (int i = 0; i < NPARTS; i++) if (c.parts & (1 << i)) m += what == 0 ? PARTS[i].acc : (what == 1 ? PARTS[i].top : PARTS[i].brake);
  return m;
}
static int partsCount(const Car &c) { int n = 0; for (int i = 0; i < NPARTS; i++) if (c.parts & (1 << i)) n++; return n; }
