  zones[ZDRAG].x = DRAG_X + 13.0f; zones[ZDRAG].z = DRAG_Z0 + 2.0f; zones[ZDRAG].col = RGB(250, 210, 40); zones[ZDRAG].kind = ZDRAG; zones[ZDRAG].label = "Драг-рейсинг";
  zones[ZRENT].x = -62; zones[ZRENT].z = 14; zones[ZRENT].col = RGB(200, 90, 230); zones[ZRENT].kind = ZRENT; zones[ZRENT].label = "Прокат гоночных";
  addBox(DRAG_X + 20.0f, DRAG_Z0 + 2.0f, 5, 3, 0, 3, RGB(40, 40, 46), true);
