      for (int q = 0; q < 4; q++) for (int s3 = -1; s3 <= 1; s3 += 2) drawBox(LC(0.3f * s3, 0.8f, 1.42f + q * 0.07f), v3(0.11f, 0.007f, 0.02f), heading, black, true);   // жалюзи по бокам от полосы
