          drawBox(LC(0.76f * s2, 1.08f, zr - 0.005f), v3(0.1f, 0.27f, 0.015f), heading, dark, true);                                // фонарь: корпус
          drawBox(LC(0.76f * s2, 1.09f, zr - 0.016f), v3(0.075f, 0.24f, 0.012f), heading, tail, false);                            //          линза
          drawBox(LC(0.76f * s2, 0.87f, zr - 0.02f), v3(0.06f, 0.035f, 0.012f), heading, RGB(240, 240, 245), false);               //          задний ход
