static const int NQ = (int)(sizeof(QBANK) / sizeof(QBANK[0]));
enum { EXQ = 10, EXMAXWRONG = 2 };
static int exQ[EXQ], exPerm[EXQ][4], exI = 0, exWrong = 0, exAns = -1;
static bool exDone = false;
static void startExam() {
  int used[64] = {0};
  for (int i = 0; i < EXQ; i++) {
    int q;
    do { q = rand() % NQ; } while (used[q]);
    used[q] = 1; exQ[i] = q;
    int p[4] = {0, 1, 2, 3};
    for (int k = 3; k > 0; k--) { int j = rand() % (k + 1); int t = p[k]; p[k] = p[j]; p[j] = t; }
    for (int k = 0; k < 4; k++) exPerm[i][k] = p[k];
  }
  exI = 0; exWrong = 0; exAns = -1; exDone = false;
  state = ST_EXAM; pSpeed = 0; stickOn = false; stX = stY = 0; gWP.on = gWP.on;
}
// вывод текста с переносом по словам; возвращает y после последней строки
static int wrapText(int x, int y, int w, const char *s, int sc, u32 col) {
  char line[256]; int n = 0;
  const char *p = s;
  line[0] = 0;
  while (*p) {
    const char *e = p; while (*e && *e != ' ') e++;
    char word[96]; int wl = (int)(e - p); if (wl > 90) wl = 90; memcpy(word, p, wl); word[wl] = 0;
    char test[256]; snprintf(test, sizeof test, n ? "%s %s" : "%s%s", line, word);
    if (n && textW(test, sc) > w) { drawText(x, y, line, sc, col, 0); y += 9 * sc + sc * 2; snprintf(line, sizeof line, "%s", word); }
    else snprintf(line, sizeof line, "%s", test);
    n++;
    p = e; while (*p == ' ') p++;
  }
  if (line[0]) { drawText(x, y, line, sc, col, 0); y += 9 * sc + sc * 2; }
  return y;
}
// подпись кнопки с переносом на 2-3 строки (кнопка рисует строки по '\n')
static void wrapLabel(const char *s, int maxw, char *out, int outn) {
  char lines[3][64]; int ln = 0; lines[0][0] = 0;
  const char *p = s;
  while (*p && ln < 3) {
    const char *e = p; while (*e && *e != ' ') e++;
    char word[64]; int wl = (int)(e - p); if (wl > 60) wl = 60; memcpy(word, p, wl); word[wl] = 0;
    char test[128]; snprintf(test, sizeof test, lines[ln][0] ? "%s %s" : "%s%s", lines[ln], word);
    if (lines[ln][0] && (textW(test, fs) > maxw || strlen(test) > 62)) { if (ln == 2) break; ln++; snprintf(lines[ln], sizeof lines[ln], "%s", word); }
    else snprintf(lines[ln], sizeof lines[ln], "%s", test);
    p = e; while (*p == ' ') p++;
  }
  out[0] = 0;
  for (int i = 0; i <= ln && i < 3; i++) { if (i) strncat(out, "\n", outn - strlen(out) - 1); strncat(out, lines[i], outn - strlen(out) - 1); }
}
static void examScreen(float dt) {
  (void)dt;
  fillRect(0, 0, IW, IH, RGB(22, 24, 32));
  int pad = fs * 4, x = pad, w = IW - pad * 2, y = pad;
  char b[160];
  if (!exDone) {
    snprintf(b, sizeof b, "ЭКЗАМЕН НА ПРАВА   вопрос %d из %d   ошибок %d (можно %d)", exI + 1, EXQ, exWrong, EXMAXWRONG);
    drawText(x, y, b, fs, RGB(255, 210, 120), 0);
    y += fs * 13;
    const Quiz &q = QBANK[exQ[exI]];
    y = wrapText(x, y, w, q.q, fs + 1, RGB(235, 238, 245));
    y += fs * 4;
    int bh = fs * 17, gap = fs * 2;
    for (int k = 0; k < 4; k++) {
      int orig = exPerm[exI][k];
      char lab[200]; wrapLabel(q.o[orig], w - fs * 6, lab, sizeof lab);
      u32 col = RGB(70, 78, 110);
      if (exAns >= 0) { if (orig == q.ok) col = RGB(50, 150, 80); else if (k == exAns) col = RGB(190, 60, 60); else col = RGB(52, 56, 72); }
      if (button(x, y, w, bh, lab, true, col) && exAns < 0) {
        exAns = k;
        if (orig != q.ok) exWrong++;
      }
      y += bh + gap;
    }
    if (exAns >= 0) {
      bool last = exI == EXQ - 1;
      int bw = fs * 80;
      if (button(IW - pad - bw, IH - pad - fs * 16, bw, fs * 16, last ? "Результат" : "Далее", true, RGB(60, 110, 200))) {
        if (last) {
          exDone = true;
          if (exWrong <= EXMAXWRONG) { licenseDay = day; gStat.exam = 1; saveGame(); say("Права получены! Действуют 30 дней"); }
        } else { exI++; exAns = -1; }
      }
    }
  } else {
    bool ok = exWrong <= EXMAXWRONG;
    drawText(IW / 2, y + fs * 8, ok ? "ЭКЗАМЕН СДАН!" : "ЭКЗАМЕН НЕ СДАН", fs + 3, ok ? RGB(120, 240, 130) : RGB(255, 100, 90), 1);
    snprintf(b, sizeof b, "Правильных ответов: %d из %d (ошибок %d, можно не больше %d)", EXQ - exWrong, EXQ, exWrong, EXMAXWRONG);
    drawText(IW / 2, y + fs * 30, b, fs, RGB(200, 205, 220), 1);
    if (ok) { snprintf(b, sizeof b, "Права действуют 30 дней: до дня %d", day + 30); drawText(IW / 2, y + fs * 42, b, fs, RGB(140, 220, 150), 1); }
    else drawText(IW / 2, y + fs * 42, "Без прав полиция оштрафует на 50% баланса: пересдай", fs, RGB(255, 190, 120), 1);
    int bw = imin(IW - pad * 2, fs * 120), bx = IW / 2 - bw / 2, by = y + fs * 62, bh = fs * 17;
    if (!ok) { if (button(bx, by, bw, bh, "Пересдать", true, RGB(60, 110, 200))) startExam(); by += bh + fs * 3; }
    if (button(bx, by, bw, bh, "В игру", true, RGB(60, 150, 90))) { state = ST_WORLD; saveGame(); }
  }
  toast(IW / 2, IH - fs * 12);
}
static void menuWalkin(float dt) {
  (void)dt;
  fillRect(0, 0, IW, IH, RGB(22, 26, 34));
  int pad = fs * 4, y = pad, w = IW - pad * 2;
  char b[200];
  drawText(IW / 2, y, "КЛИЕНТ ПРИЕХАЛ К МАСТЕРСКОЙ", fs + 2, RGB(255, 200, 110), 1); y += fs * 16;
  if (gWalk.phase != 2) { state = ST_WORLD; return; }
  const Car &c = gWalk.car;
  snprintf(b, sizeof b, "Машина: %s   Состояние %d%%", MOD[clampi(c.model, 0, NMODEL - 1)].name, avgc(c)); drawText(IW / 2, y, b, fs, RGB(235, 238, 245), 1); y += fs * 11;
  maskText(b, sizeof b, c); fitText(b, w); drawText(IW / 2, y, b, fs, RGB(255, 190, 90), 1); y += fs * 11;
  snprintf(b, sizeof b, "Награда: $%d (с учётом рейтинга $%d). Машину заберёт здесь же, в мастерской", c.reward, c.reward + (int)(c.reward * (gRep - 3.0f) * 0.05f));
  fitText(b, w); drawText(IW / 2, y, b, fs, RGB(140, 230, 150), 1); y += fs * 11;
  snprintf(b, sizeof b, "Клиент подождёт ещё %d с", (int)gWalk.wait); drawText(IW / 2, y, b, fs, RGB(170, 180, 200), 1); y += fs * 14;
  bool room = (int)garage.size() < garageCap();
  if (!room) { drawText(IW / 2, y, "ГАРАЖ ПОЛОН: ОСВОБОДИ МЕСТО ИЛИ АРЕНДУЙ СТОЯНКУ", fs, RGB(255, 120, 110), 1); y += fs * 11; }
  int bw = imin(w, fs * 190), bh = fs * 16, bx = IW / 2 - bw / 2;
  if (button(bx, y, bw, bh, "Принять заказ", room, RGB(60, 150, 90))) {
    garage.push_back(gWalk.car);
    cur = (int)garage.size() - 1;
    gWalk.phase = 0;
    say("МАШИНА КЛИЕНТА В ГАРАЖЕ. ПОЧИНИ И ОТДАЙ ЕЁ В МАСТЕРСКОЙ");
    saveGame();
    state = ST_WORK; tabW = 0; sel = 0; pvYaw = 0.6f;
    return;
  }
  y += bh + fs * 3;
  if (button(bx, y, bw, bh, "Отказать", true, RGB(180, 80, 60))) { gWalk.phase = 3; say("КЛИЕНТ УЕХАЛ"); state = ST_WORLD; return; }
  y += bh + fs * 3;
  if (button(bx, y, bw, bh, "Позже (в мастерскую)", true, RGB(90, 96, 120))) { state = ST_WORK; tabW = 0; sel = 0; pvYaw = 0.6f; }
  toast(IW / 2, IH - fs * 10);
}
static void trkStart(int mode) {
  gTrk.on = true; gTrk.mode = mode; gTrk.phase = 0; gTrk.t = 0; gTrk.lapT = 0; gTrk.lastLap = 0; gTrk.cp = 0; gTrk.lap = 0;
  gTrk.laps = mode == 2 ? 2 : 999; gTrk.fee = mode == 2 ? 300 : 0; gTrk.pfin = false; gTrk.offT = 0; gTrk.nrec = 0; gTrk.place = 0;
  money -= gTrk.fee;
  const ModelInfo &me = MOD[clampi(garage[cur].model, 0, NMODEL - 1)];
  const Car &pc2 = garage[cur];
  float oilF = pc2.oil >= 30 ? 1.0f : 0.6f + 0.4f * pc2.oil / 30.0f, filtF = pc2.filt >= 40 ? 1.0f : 0.7f + 0.3f * pc2.filt / 40.0f;
  float engF = (0.5f + 0.5f * pc2.cond[0] / 100.0f) * oilF * filtF;
  float topP = (115.0f + (me.vmax - 14.0f) * 4.1f) / 3.6f * (1.0f + 0.08f * pc2.tune) * engF;
  float accP = me.acc * 0.342f * (1.0f + 0.1f * pc2.tune) * (0.6f + 0.4f * engF);
  const float lat[TRK_NAI] = {1.75f, -1.75f, 1.75f}, s0[TRK_NAI] = {-6.0f, -6.0f, -18.0f};
  for (int i = 0; i < TRK_NAI; i++) {
    int cand[NMODEL]; int nc = 0;
    for (int m = 0; m < NMODEL; m++) if (modelAvail(m) && fabsf(MOD[m].acc - me.acc) <= 5.0f && fabsf(MOD[m].vmax - me.vmax) <= 10.0f) cand[nc++] = m;
    int om = nc ? cand[rand() % nc] : garage[cur].model;
    gTrk.acar[i] = newCar(om, 85, 100);
    u32 c = PALETTE[rand() % 8]; gTrk.acar[i].col[0] = CR(c); gTrk.acar[i].col[1] = CG(c); gTrk.acar[i].col[2] = CB(c); gTrk.acar[i].dirt = 0;
    gTrk.atop[i] = topP * frand(0.9f, 1.02f); gTrk.aacc[i] = accP * frand(0.85f, 1.0f);
    gTrk.as[i] = s0[i]; gTrk.av[i] = 0; gTrk.alat[i] = lat[i]; gTrk.afin[i] = false;
  }
  pPos = v3(-12.0f, 0, -120.0f - 1.75f); pHead = 1.5708f; camYaw = pHead; pSpeed = 0; stickOn = false; stX = stY = 0;
  for (int k = 0; k < 3; k++) for (int i = 0; i < NNPC; i++) if (npcs[i].road == 0 || npcs[i].road == 2) respawnNpc(i);
  say(mode == 2 ? "Гонка: 2 круга по часовой стрелке. Жди зелёный!" : "Тренировка: круги по часовой стрелке. Жди зелёный!");
  state = ST_WORLD;
}
