static void dragStart(int bet) {
  const ModelInfo &me = MOD[clampi(garage[cur].model, 0, NMODEL - 1)];
  int cand[NMODEL]; int nc = 0;
  for (int m = 0; m < NMODEL; m++) if (modelAvail(m) && fabsf(MOD[m].acc - me.acc) <= 4.0f && fabsf(MOD[m].vmax - me.vmax) <= 8.0f) cand[nc++] = m;
  int om = nc ? cand[rand() % nc] : garage[cur].model;
  gDrag.opp = newCar(om, 85, 100);
  u32 pc = PALETTE[rand() % 8]; gDrag.opp.col[0] = CR(pc); gDrag.opp.col[1] = CG(pc); gDrag.opp.col[2] = CB(pc); gDrag.opp.dirt = 0;
  // сила соперника - как у твоей машины с учётом её состояния и тюнинга (честный заезд, решает старт)
  const Car &pc2 = garage[cur];
  float oilF = pc2.oil >= 30 ? 1.0f : 0.6f + 0.4f * pc2.oil / 30.0f, filtF = pc2.filt >= 40 ? 1.0f : 0.7f + 0.3f * pc2.filt / 40.0f;
  float engF = (0.5f + 0.5f * pc2.cond[0] / 100.0f) * oilF * filtF;
  float topP = (115.0f + (me.vmax - 14.0f) * 4.1f) / 3.6f * (1.0f + 0.08f * pc2.tune) * engF;
  float accP = me.acc * 0.342f * (1.0f + 0.1f * pc2.tune) * (0.6f + 0.4f * engF);
  gDrag.otop = topP * frand(0.95f, 1.03f);
  gDrag.oacc = accP * frand(0.9f, 1.04f);
  gDrag.react = frand(0.15f, 0.55f);
  gDrag.oz = DRAG_Z0; gDrag.ov = 0; gDrag.t = 0; gDrag.phase = 0; gDrag.bet = bet;
  gDrag.pfin = gDrag.ofin = false; gDrag.ptime = gDrag.otime = 0; gDrag.on = true;
  pPos = v3(DRAG_X + 1.75f, 0, DRAG_Z0); pHead = 0; camYaw = 0; pSpeed = 0; stickOn = false; stX = stY = 0;
  for (int k = 0; k < 3; k++) for (int i = 0; i < NNPC; i++) if (npcs[i].axis == 0 && npcs[i].road == 0) respawnNpc(i);
  char b[96]; snprintf(b, sizeof b, "Соперник: %s. Жди зелёный!", MOD[om].name); say(b);
  state = ST_WORLD;
}
